def xyz_to_srgb_d65(xyz):
    x, y, z = xyz
    r = x * 3.2412048460359184 + y * -1.5373831775700948 + z * -0.49889188498974524
    g = x * -0.96931388664992746 + y * 1.8759675015077215 + z * 0.041578486811115499
    b = x * 0.055634111741654647 + y * -0.20397695888897666 + z * 1.0575674516354685
    return (r, g, b)

