def read_spectral_image(filename):
    with open(filename, "r") as f:
        lines = f.readlines()

    width = int(lines[0].strip())
    height = int(lines[1].strip())

    spectra = np.array(
        [
            np.fromstring(line.strip(), sep=",")
            for line in lines[2:]
            if line.strip()
        ],
        dtype=np.float32
    )

    expected_pixels = height * width
    if spectra.shape[0] != expected_pixels:
        raise ValueError(
            f"Expected {expected_pixels} pixels, got {spectra.shape[0]}"
        )

    bands = spectra.shape[1]
    return spectra.reshape(height, width, bands)


def convert_file(input_file, output_file):
    print(f"\nProcessing: {input_file}")

    spectral_image = read_spectral_image(input_file)
    height, width, bands = spectral_image.shape

    print("Height:", height)
    print("Width:", width)
    print("Bands:", bands)

    rgb_image = np.zeros((height, width, 3), dtype=np.float32)

    for y in range(height):
        for x in range(width):
            rgb_image[y, x] = spec_to_RGB(spectral_image[y, x])

    header = OpenEXR.Header(width, height)
    FLOAT = Imath.PixelType(Imath.PixelType.FLOAT)

    header["channels"] = {
        "R": Imath.Channel(FLOAT),
        "G": Imath.Channel(FLOAT),
        "B": Imath.Channel(FLOAT),
    }

    exr = OpenEXR.OutputFile(output_file, header)

    exr.writePixels({
        "R": rgb_image[:, :, 0].astype(np.float32).tobytes(),
        "G": rgb_image[:, :, 1].astype(np.float32).tobytes(),
        "B": rgb_image[:, :, 2].astype(np.float32).tobytes(),
    })

    exr.close()

    print(f"Saved: {output_file}")


def main():
    parser = argparse.ArgumentParser(
        description="Convert hyperspectral images in a folder to RGB EXR"
    )

    parser.add_argument(
        "input_folder",
        type=str,
        help="Folder containing hyperspectral files"
    )

    parser.add_argument(
        "-o",
        "--output_folder",
        default="converted_exrs",
        help="Output folder"
    )

    args = parser.parse_args()

    os.makedirs(args.output_folder, exist_ok=True)

    files = glob.glob(os.path.join(args.input_folder, "*.txt"))

    if not files:
        print("No input files found.")
        return

    for filename in files:
        basename = os.path.splitext(os.path.basename(filename))[0]
        output = os.path.join(
            args.output_folder,
            basename + ".exr"
        )

        convert_file(filename, output)


if __name__ == "__main__":
    main()